const event = $json.body && typeof $json.body === 'object' ? $json.body : $json;
if (event.event_type !== 'matches.completed') throw new Error('Workflow C requires a matches.completed event');
if (event.status !== 'completed') throw new Error('Workflow C requires a completed match event');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(event.upload_batch_id))) throw new Error('Workflow C requires a UUID batch id');
const metrics = event.metrics || {};
if (Number(metrics.naive) !== Number(metrics.evaluated) || Number(metrics.evaluated) !== Number(metrics.stored) || Number(metrics.candidates) > Number(metrics.naive) || Number(metrics.top_k_highlights) > Number(metrics.eligible) + Number(metrics.may_qualify) + Number(metrics.unknown)) throw new Error('Workflow C received invalid match metrics');
if (event.demo_only === true) { const expected = String($env.DEMO_NOTIFICATION_TOKEN || ''); if (!expected || String(event.demo_token || '') !== expected) throw new Error('invalid demo notification token'); if (!Array.isArray(event.demo_targets) || event.demo_targets.length < 1 || event.demo_targets.length > 2) throw new Error('demo notification must target one or two users'); }
return [{ json: { ...event, verified: true } }];

const awsDemo = String($env.AWS_DEMO_MODE || 'false').toLowerCase() === 'true';
if (!awsDemo) return $input.all();
const recipients = String($env.AWS_DEMO_RECIPIENTS || '').split(',').map(value => value.trim().toLowerCase()).filter(Boolean);
const assigned = new Map();
return $input.all().map(item => { const row = item.json; if (row.no_match || !row.user_id) return item; const key = String(row.user_id); if (!assigned.has(key)) assigned.set(key, recipients[assigned.size] || ''); return { json: { ...row, delivery_recipient: assigned.get(key) } }; });

const event = $items('Verify Match Event')[0].json;
const rows = $input.all().map(item => item.json).filter(row => !row.no_match && row.user_id && row.email);
if (!rows.length) return [{ json: { upload_batch_id: event.upload_batch_id, no_matches: true, template_key: 'eligible-loans-v1' } }];
const allowlist = new Set(String($env.DEMO_RECIPIENTS || '').split(',').map(value => value.trim().toLowerCase()).filter(Boolean));
if (!allowlist.size) throw new Error('DEMO_RECIPIENTS must be a non-empty controlled allowlist');
const targets = new Map((event.demo_targets || []).map(target => [String(target.user_id), String(target.recipient).trim().toLowerCase()]));
if (event.demo_only === true && targets.size !== event.demo_targets.length) throw new Error('demo targets contain duplicate users');
const groups = new Map();
for (const row of rows) {
  const sourceRecipient = String(row.email).trim().toLowerCase();
  const recipient = String(row.delivery_recipient || sourceRecipient).trim().toLowerCase();
  if (!recipient || /[\r\n]/.test(recipient)) throw new Error('recipient contains an unsafe character');
  if (event.demo_only === true && (!targets.has(String(row.user_id)) || targets.get(String(row.user_id)) !== recipient || recipient === sourceRecipient)) throw new Error('demo delivery recipient mapping is invalid');
  const key = `${row.user_id}:${recipient}`;
  const current = groups.get(key) || { upload_batch_id: event.upload_batch_id, user_uuid: row.user_id, recipient, user_name: row.user_name, product_ids: [], product_names: [], decisions: [] };
  current.product_ids.push(row.product_id);
  current.product_names.push(row.product_name);
  current.decisions.push(row.decision);
  groups.set(key, current);
}
return [...groups.values()].map(group => {
  const allowed = allowlist.has(group.recipient);
  if (event.demo_only === true && !allowed) throw new Error('demo recipient is not allowlisted');
  const qualified = group.product_names.length ? group.product_names.join(', ') : 'no matching products';
  return { json: { ...group, template_key: 'eligible-loans-demo-v1', delivery_status: allowed ? 'queued' : 'blocked', allowlisted: allowed, subject: 'Your loan eligibility results', text: `Hello ${group.user_name},\n\nBased on the information you supplied, you may qualify for: ${qualified}.\n\nThis is an informational result, not a lending decision.` } };
});

const original = $items('Group Matches and Apply DEMO_RECIPIENTS Allowlist')[$itemIndex].json;
const response = $json || {};
const providerMessageId = response.MessageId || response.messageId || response.SendEmailResponse?.MessageId || response.SendEmailResponse?.SendEmailResult?.MessageId || response.SendEmailResult?.MessageId || `ses-${original.recipient}`;
return [{ json: { ...original, delivery_status: 'sent', provider_message_id: providerMessageId } }];

const event = $items('Verify Match Event')[0].json;
const noMatches = $items('Group Matches and Apply DEMO_RECIPIENTS Allowlist')[0]?.json?.no_matches === true;
return [{ json: { status: 'completed', upload_batch_id: event.upload_batch_id, deliveries_recorded: noMatches ? 0 : $input.all().length, no_matches: noMatches } }];
